/**
 * One scenario per check of debtor-chasing-build-standard, for Owing Today.
 *
 * Generated by `npx @aipathway/conformance init debtor-chasing-build-standard`,
 * then written out. The checks are fetched at run time from
 * https://aipathway.com.au/explore-ai/debtor-chasing-build-standard
 *
 * Each `holds` reads the world the runner owns (the recorded port calls, the
 * runs submitted through `rank`, the gate decisions, the escalations), never
 * the build. A build that does nothing, or goes around the ports, leaves those
 * empty and fails every check below; probes.mjs proves it.
 *
 * The clock starts at Monday 21 September 2026, 2pm in Brisbane, unless a
 * scenario says otherwise.
 */

import { DebtorWorld } from "@aipathway/conformance";

/** The four buckets, closed, as the standard names them. No free-text bucket passes. */
const BUCKETS = ["just_late", "drifting", "hard", "broken_promise"];

const DAY = 86_400_000;
const START = new Date("2026-09-21T04:00:00.000Z");
const OWNER = "Bec Hartley (office manager, receivables)";

const at = (daysFromStart) => new Date(START.getTime() + daysFromStart * DAY).toISOString();
/** An invoice for `dollars`, issued `issuedAgo` days before the start, due `dueAgo` days before it (negative: not yet due). */
const inv = (id, customerId, dollars, issuedAgo, dueAgo, extra = {}) => ({
  id,
  customerId,
  amount: Math.round(dollars * 100),
  issuedAt: at(-issuedAgo),
  dueAt: at(-dueAgo),
  ...extra,
});
const cust = (id, name, extra = {}) => ({ id, name, timezone: "Australia/Brisbane", ...extra });

const tick = (build, world) => build(world.ports(), { event: "schedule.tick" });

/** The customers on the dial list of a run, in order. Lifted rows are not on it. */
const dialOrder = (run) => run.filter((e) => !e.excludedReason).map((e) => e.customerId);

/** Every queue the build put in front of the owner, flattened. */
const queued = (world) =>
  world.escalations
    .filter((e) => e.reason === "debtor.queue_ready")
    .flatMap((e) => {
      try {
        const d = JSON.parse(e.detail ?? "{}");
        return d.exception_owner === OWNER && Array.isArray(d.queue) ? d.queue : [];
      } catch {
        return [];
      }
    });

const escalationFor = (world, reason, customerId) =>
  world.escalations.some((e) => {
    if (e.reason !== reason) return false;
    try {
      const d = JSON.parse(e.detail ?? "{}");
      return d.exception_owner === OWNER && d.customer_id === customerId;
    } catch {
      return false;
    }
  });

const describe = (world) =>
  `${world.calls.length} port call(s); runs ${world.runs.map((r) => `[${r.map((e) => `${e.customerId}:${e.bucket}${e.excludedReason ? `/${e.excludedReason}` : ""}`).join(" ")}]`).join(" ") || "none"}; ` +
  `gate ${world.gateDecisions.map((g) => `${g.customerId}:${g.decision.allowed ? "ok" : g.decision.reason}`).join(" ") || "none"}; ` +
  `escalations ${world.escalations.map((e) => e.reason).join(" ") || "none"}; promises ${world.promises.length}; dials ${world.dials.length}`;

export const scenarios = [
  {
    checkId: "coverage-measured",
    // 1. Closed by evidence, not by a run. The build carries COVERAGE with a
    // null figure until the business measures its own ledger; it is never
    // scored green on a declaration.
    world: () => new DebtorWorld(),
    drive: () => {},
    holds: () => false,
    describe: () => "No software result. The business attaches the mobile share of its overdue book and when it was counted.",
  },
  {
    checkId: "overdue-off-due-date",
    // 2. LONG was issued 120 days ago on 130-day terms: not due for ten more
    // days. Two others are past their due date, one issued only ten days ago.
    world: () =>
      new DebtorWorld({
        customers: [cust("C-LONG", "Long Terms Civil Pty Ltd"), cust("C-SHORT", "Short Terms Plumbing"), cust("C-OLD", "Ridge Roofing")],
        invoices: [inv("INV-201", "C-LONG", 6400, 120, -10), inv("INV-202", "C-SHORT", 900, 10, 3), inv("INV-203", "C-OLD", 2100, 40, 10)],
      }),
    drive: tick,
    holds: (world) => {
      if (world.runs.length !== 1) return false;
      const ids = world.lastRun.flatMap((e) => e.invoiceIds);
      const readFirst = world.calls.findIndex((c) => c.port === "read_ledger") < world.calls.findIndex((c) => c.port === "rank");
      return readFirst && !ids.includes("INV-201") && ids.includes("INV-202") && ids.includes("INV-203") && ids.length === 2;
    },
    describe,
  },
  {
    checkId: "four-buckets",
    // 3. One customer for each bucket. BROKE said it would pay by 14 September.
    world: () =>
      new DebtorWorld({
        customers: [cust("C-JL", "Just Late Electrical"), cust("C-DR", "Drifting Tiling"), cust("C-HD", "Hard Yards Concreting"), cust("C-BP", "Broke Promise Fencing")],
        invoices: [inv("INV-301", "C-JL", 700, 19, 5), inv("INV-302", "C-DR", 1500, 39, 25), inv("INV-303", "C-HD", 3200, 74, 60), inv("INV-304", "C-BP", 1100, 34, 20)],
        promises: [{ customerId: "C-BP", date: "2026-09-14", amount: 110000, capturedAt: at(-12) }],
      }),
    drive: tick,
    holds: (world) => {
      const want = { "C-JL": "just_late", "C-DR": "drifting", "C-HD": "hard", "C-BP": "broken_promise" };
      const run = world.lastRun;
      return (
        world.runs.length === 1 &&
        run.length === 4 &&
        run.every((e) => BUCKETS.includes(e.bucket)) &&
        Object.entries(want).every(([id, bucket]) => run.find((e) => e.customerId === id)?.bucket === bucket)
      );
    },
    describe,
  },
  {
    checkId: "broken-promise-outranks",
    // 4. A $300 broken promise beside a $25,000 invoice that is six days late.
    world: () =>
      new DebtorWorld({
        customers: [cust("C-SMALL", "Small Promise Landscaping"), cust("C-BIG", "Big Late Builders")],
        invoices: [inv("INV-401", "C-SMALL", 300, 34, 20), inv("INV-402", "C-BIG", 25000, 20, 6)],
        promises: [{ customerId: "C-SMALL", date: "2026-09-15", amount: null, capturedAt: at(-10) }],
      }),
    drive: tick,
    holds: (world) => {
      const order = dialOrder(world.lastRun);
      return (
        world.runs.length === 1 &&
        order.length === 2 &&
        order[0] === "C-SMALL" &&
        order[1] === "C-BIG" &&
        world.lastRun.find((e) => e.customerId === "C-SMALL")?.bucket === "broken_promise"
      );
    },
    describe,
  },
  {
    checkId: "rank-by-amount-at-risk",
    // 5. Four drifting customers. OLD is the oldest and the smallest; NEW is
    // the newest and the largest; T1 and T2 owe the same, so age decides them.
    world: () =>
      new DebtorWorld({
        customers: [cust("C-OLD", "Old Small Glazing"), cust("C-NEW", "New Large Cabinets"), cust("C-T1", "Tie Older Painting"), cust("C-T2", "Tie Newer Painting")],
        invoices: [
          inv("INV-501", "C-OLD", 500, 54, 40),
          inv("INV-502", "C-NEW", 9000, 30, 16),
          inv("INV-503", "C-T1", 2000, 44, 30),
          inv("INV-504", "C-T2", 2000, 34, 20),
        ],
      }),
    drive: tick,
    holds: (world) =>
      world.runs.length === 1 &&
      world.lastRun.every((e) => e.bucket === "drifting") &&
      JSON.stringify(dialOrder(world.lastRun)) === JSON.stringify(["C-NEW", "C-T1", "C-T2", "C-OLD"]),
    describe,
  },
  {
    checkId: "one-customer-one-conversation",
    // 6. One customer with six overdue invoices, beside one with a single invoice.
    world: () =>
      new DebtorWorld({
        customers: [cust("C-SIX", "Six Stage Homes"), cust("C-ONE", "One Off Electrical")],
        invoices: [
          inv("INV-601", "C-SIX", 1200, 60, 46),
          inv("INV-602", "C-SIX", 800, 50, 36),
          inv("INV-603", "C-SIX", 450, 40, 26),
          inv("INV-604", "C-SIX", 2300, 30, 16),
          inv("INV-605", "C-SIX", 150, 20, 6),
          inv("INV-606", "C-SIX", 990, 16, 2),
          inv("INV-607", "C-ONE", 300, 20, 6),
        ],
      }),
    drive: tick,
    holds: (world) => {
      const six = world.lastRun.filter((e) => e.customerId === "C-SIX");
      const ids = six[0]?.invoiceIds ?? [];
      const reminders = queued(world).filter((q) => q.customerId === "C-SIX");
      return (
        world.runs.length === 1 &&
        six.length === 1 &&
        six[0].amount === 589000 &&
        ids.length === 6 &&
        ["INV-601", "INV-602", "INV-603", "INV-604", "INV-605", "INV-606"].every((id) => ids.includes(id)) &&
        reminders.length === 1 &&
        world.gateDecisions.filter((g) => g.customerId === "C-SIX").length === 1
      );
    },
    describe,
  },
  {
    checkId: "relationship-balances-excluded",
    // 7. BIG owes $180,000 against a $40,000 threshold. SMALL owes $1,200.
    world: () =>
      new DebtorWorld({
        customers: [cust("C-BIG", "Major Developments Pty Ltd"), cust("C-SMALL", "Small Reno Co")],
        invoices: [inv("INV-701", "C-BIG", 180000, 50, 20), inv("INV-702", "C-SMALL", 1200, 30, 9)],
      }),
    drive: tick,
    holds: (world) => {
      const big = world.lastRun.find((e) => e.customerId === "C-BIG");
      return (
        world.runs.length === 1 &&
        Boolean(big) &&
        big.excludedReason === "relationship_account" &&
        !dialOrder(world.lastRun).includes("C-BIG") &&
        !world.gateDecisions.some((g) => g.customerId === "C-BIG") &&
        !queued(world).some((q) => q.customerId === "C-BIG") &&
        escalationFor(world, "debtor.relationship_account", "C-BIG") &&
        queued(world).some((q) => q.customerId === "C-SMALL")
      );
    },
    describe,
  },
  {
    checkId: "promise-is-an-object",
    // 8. DISP's invoice already carries a dispute. Its reply on the reminder
    // thread (Monday) says Friday with no figure. VAGUE replies with no date at all.
    world: () =>
      new DebtorWorld({
        customers: [cust("C-DISP", "Disputed Decks"), cust("C-VAGUE", "Vague Answers Pty Ltd")],
        invoices: [inv("INV-801", "C-DISP", 5200, 34, 20, { disputed: true }), inv("INV-802", "C-VAGUE", 800, 30, 16)],
      }),
    drive: async (build, world) => {
      await build(world.ports(), { event: "email.received", messageId: "MSG-8001", invoiceId: "INV-801", said: "Thanks for the reminder, we'll pay it Friday." });
      await build(world.ports(), { event: "email.received", messageId: "MSG-8002", invoiceId: "INV-802", said: "Yep, we'll get to it soon." });
      await tick(build, world);
    },
    holds: (world) => {
      const call = world.calls.find((c) => c.port === "record_promise" && c.request?.customerId === "C-DISP");
      const p = world.promises.find((x) => x.customerId === "C-DISP");
      const stillDisputed = world.ports().readLedger().find((i) => i.id === "INV-801")?.disputed === true;
      const disp = world.lastRun.find((e) => e.customerId === "C-DISP");
      return (
        Boolean(call) &&
        call.request.date === "2026-09-25" &&
        call.request.amount === null &&
        typeof call.response?.capturedAt === "string" &&
        Boolean(p) &&
        p.amount === null &&
        p.capturedAt.length > 0 &&
        stillDisputed &&
        // the promise sits on a disputed invoice: the dispute still decides, so the row stays lifted out
        (disp === undefined || disp.excludedReason === "dispute_open") &&
        !queued(world).some((q) => q.customerId === "C-DISP") &&
        // no date, no promise: the vague reply went to the owner instead
        !world.promises.some((x) => x.customerId === "C-VAGUE") &&
        escalationFor(world, "debtor.reply_without_date", "C-VAGUE")
      );
    },
    describe,
  },
  {
    checkId: "promised-date-is-followup",
    // 9. PROM promised Saturday 26 September, five days out. A run each morning
    // for the next four days, then one on the promised date itself.
    world: () =>
      new DebtorWorld({
        customers: [cust("C-PROM", "Promised Plastering"), cust("C-STEADY", "Steady Late Sparkies")],
        invoices: [inv("INV-901", "C-PROM", 5200, 45, 15), inv("INV-902", "C-STEADY", 800, 30, 4)],
        promises: [{ customerId: "C-PROM", date: "2026-09-26", amount: 520000, capturedAt: at(0) }],
      }),
    drive: async (build, world) => {
      for (let d = 1; d <= 5; d++) {
        world.advance(DAY);
        await tick(build, world);
      }
    },
    holds: (world) => {
      if (world.runs.length !== 5) return false;
      const before = world.runs.slice(0, 4);
      const dueDay = world.runs[4];
      const promGated = world.gateDecisions.filter((g) => g.customerId === "C-PROM");
      return (
        before.every((run) => !run.some((e) => e.customerId === "C-PROM") && run.some((e) => e.customerId === "C-STEADY")) &&
        dueDay.some((e) => e.customerId === "C-PROM") &&
        promGated.length === 1 &&
        promGated[0].at.startsWith("2026-09-26")
      );
    },
    describe,
  },
  {
    checkId: "gate-under-ranking",
    // 10. TOP is the top-ranked row. Monday 8:30pm in Brisbane; Tuesday 2pm,
    // a public holiday; Wednesday 2pm, when the ledger shows TOP paid between
    // the ranking and the gate. NEXT, a smaller row, is cleared on Wednesday,
    // so a gate that holds everything does not pass either.
    world: () =>
      new DebtorWorld({
        now: new Date("2026-09-21T10:30:00.000Z"),
        customers: [cust("C-TOP", "Top Of The Book Homes"), cust("C-NEXT", "Next Down Joinery")],
        invoices: [inv("INV-1001", "C-TOP", 38000, 60, 30), inv("INV-1002", "C-NEXT", 1200, 30, 8)],
        holidays: ["2026-09-22"],
      }),
    drive: async (build, world) => {
      await tick(build, world); // Monday 8:30pm
      world.advance(17.5 * 60 * 60_000); // Tuesday 2pm, public holiday
      await tick(build, world);
      world.advance(DAY); // Wednesday 2pm
      const p = world.ports();
      await build(
        {
          ...p,
          rank: (entries) => {
            p.rank(entries);
            world.markPaid("INV-1001"); // the money lands after the ranking, before the gate
          },
        },
        { event: "schedule.tick" },
      );
    },
    holds: (world) => {
      if (world.runs.length !== 3) return false;
      const topFirst = world.runs.every((run) => dialOrder(run)[0] === "C-TOP");
      const top = world.gateDecisions.filter((g) => g.customerId === "C-TOP");
      const reasons = JSON.stringify(top.map((g) => g.decision.reason)) === JSON.stringify(["outside_hours", "public_holiday", "already_paid"]);
      const allHeld = top.length === 3 && top.every((g) => g.decision.allowed === false);
      // Underneath: in every run the rank call comes before that run's first gate call.
      const ranks = world.calls.map((c, i) => (c.port === "rank" ? i : -1)).filter((i) => i >= 0);
      const firstGate = world.calls.findIndex((c) => c.port === "gate");
      const underneath =
        ranks.length === 3 &&
        firstGate > ranks[0] &&
        ranks.every((r, k) => {
          const end = ranks[k + 1] ?? world.calls.length;
          return world.calls.slice(r + 1, end).some((c) => c.port === "gate" && c.request?.customerId === "C-TOP");
        });
      const nextCleared = world.gateDecisions.some((g) => g.customerId === "C-NEXT" && g.decision.allowed === true);
      return (
        topFirst &&
        reasons &&
        allHeld &&
        underneath &&
        world.dials.length === 0 &&
        !queued(world).some((q) => q.customerId === "C-TOP") &&
        nextCleared &&
        queued(world).some((q) => q.customerId === "C-NEXT")
      );
    },
    describe,
  },
  {
    checkId: "exceptions-attributable",
    // 11. Two rows held at 8:30pm Monday. The owner approves an exception for
    // ASKED (the customer asked to be texted after work). One for UNSIGNED
    // arrives with nobody named and must be refused, with nothing released.
    world: () =>
      new DebtorWorld({
        now: new Date("2026-09-21T10:30:00.000Z"),
        customers: [cust("C-ASKED", "After Work Carpentry"), cust("C-UNSIGNED", "Unsigned Drainage")],
        invoices: [inv("INV-1101", "C-ASKED", 4100, 50, 20), inv("INV-1102", "C-UNSIGNED", 3900, 50, 20)],
      }),
    drive: async (build, world) => {
      await tick(build, world);
      world.advance(5 * 60_000);
      await build(world.ports(), { event: "exception.closed", customerId: "C-ASKED", reason: "customer asked to be contacted after 8pm", approver: "Bec Hartley" });
      await build(world.ports(), { event: "exception.closed", customerId: "C-UNSIGNED", reason: "chase it anyway" });
    },
    holds: (world) => {
      const heldFirst =
        world.gateDecisions.filter((g) => g.decision.allowed === false && g.decision.reason === "outside_hours").map((g) => g.customerId).sort().join() === "C-ASKED,C-UNSIGNED";
      const o = world.overrides.find((x) => x.customerId === "C-ASKED");
      const recorded = Boolean(o) && o.approver === "Bec Hartley" && o.reason === "customer asked to be contacted after 8pm" && typeof o.at === "string" && o.at.length > 0;
      const refused = world.refusedOverrides.some((r) => r.customerId === "C-UNSIGNED") && !world.overrides.some((x) => x.customerId === "C-UNSIGNED");
      const released = queued(world).filter((q) => q.customerId === "C-ASKED");
      return (
        heldFirst &&
        recorded &&
        refused &&
        released.length === 1 &&
        released[0].approved_by === "Bec Hartley" &&
        !queued(world).some((q) => q.customerId === "C-UNSIGNED") &&
        escalationFor(world, "debtor.override_refused", "C-UNSIGNED") &&
        world.dials.length === 0
      );
    },
    describe,
  },
];

// Check 12 is a real run on a real ledger and number. with_us on the stub.
export const liveScenarios = [
  {
    checkId: "pass-test",
    world: () => new DebtorWorld(),
    drive: (build, world) => build(world.ports()),
    holds: () => false,
    describe: (world) => `${world.calls.length} port call(s)`,
  },
];
